Description: {{ $json.data.feature_description }}

Generate exactly 5 tasks. Keep responses short to minimize cost.

parameters.jsCode:
// Cost-optimized task processing
try {
  const aiResponse = JSON.parse($input.item.json.message.content);
  const featureData = $input.item.json;

  const featureId = featureData.data ? featureData.data.feature_id : featureData.feature_id;
  const tasks = aiResponse.tasks || [];

  // Limit to 5 tasks max to control costs
  const limitedTasks = tasks.slice(0, 5).map(task => ({
    name: task.name || 'Task',
    description: task.description || '',
    priority: Math.min(10, Math.max(1, parseInt(task.priority) || 5)),
    estimated_hours: Math.min(12, parseInt(task.estimated_hours) || 4),
    skills: Array.isArray(task.skills) ? task.skills.slice(0, 3) : []
  }));

  return [{
    feature_id: featureId,
    tasks: limitedTasks,
    cost_optimized: true
  }];
} catch (error) {
  // Cheap fallback - no AI cost
  const featureData = $input.item.json;
  const featureId = featureData.data ? featureData.data.feature_id : featureData.feature_id;

  return [{
    feature_id: featureId,
    tasks: [
      { name: 'Research Requirements', description: 'Analyze and document requirements', priority: 7, estimated_hours: 2, skills: ['Analysis'] },
      { name: 'Design Solution', description: 'Create technical design', priority: 8, estimated_hours: 4, skills: ['Design'] },
      { name: 'Implement Core', description: 'Build main functionality', priority: 9, estimated_hours: 8, skills: ['Development'] },
      { name: 'Test Implementation', description: 'Create and run tests', priority: 6, estimated_hours: 3, skills: ['Testing'] },
      { name: 'Document Feature', description: 'Write documentation', priority: 4, estimated_hours: 2, skills: ['Documentation'] }
    ],
    cost_optimized: true,
    fallback_used: true
  }];
}
